// 后台列表：全部设置 + 对外资料 + 角色卡名/文件夹名 + 窗口内用量 + 进行中的匹配数。
func (q *Queries) ListBots(ctx context.Context) ([]ListBotsRow, error) {
	rows, err := q.db.Query(ctx, listBots)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListBotsRow{}
	for rows.Next() {
		var i ListBotsRow
		if err := rows.Scan(
			&i.ID,
			&i.IdentityID,
			&i.Label,
			&i.CardID,
			&i.MediaFolderID,
			&i.Enabled,
			&i.Model,
			&i.Temperature,
			&i.MaxOutputTokens,
			&i.ServeMatch,
			&i.ServeBottle,
			&i.MaxActiveMatches,
			&i.TotalTokenLimit,
			&i.TotalReplyLimit,
			&i.WindowSeconds,
			&i.WindowTokenLimit,
			&i.WindowReplyLimit,
			&i.ConvReplyLimit,
			&i.ConvMinIntervalSeconds,
			&i.ConvMediaLimit,
			&i.ReplyDelayMinMs,
			&i.ReplyDelayMaxMs,
			&i.TypingMsPerChar,
			&i.BottleIntervalSeconds,
			&i.UsedTokens,
			&i.UsedReplies,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Nickname,
			&i.AvatarSeed,
			&i.PublicCode,
			&i.Gender,
			&i.Age,
			&i.Province,
			&i.ProvincePublic,
			&i.Tags,
			&i.CleanMode,
			&i.MatchGender,
			&i.MatchSameProvince,
			&i.VipUntil,
			&i.CardName,
			&i.FolderName,
			&i.WindowTokens,
			&i.WindowPromptTokens,
			&i.WindowCachedTokens,
			&i.WindowReplies,
			&i.ActiveMatches,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

