const listOpenMatchConversationsForIdentity = `-- name: ListOpenMatchConversationsForIdentity :many
SELECT c.id
FROM conversations c
JOIN conversation_members cm
  ON cm.conversation_id = c.id AND cm.identity_id = $1 AND cm.left_at IS NULL
WHERE c.kind = 'match' AND c.ended_at IS NULL
`

// 删除 bot 时用：先把这些会话以 peer_left 结束（走 conversation.Service.End 才能通知对端）。
func (q *Queries) ListOpenMatchConversationsForIdentity(ctx context.Context, identityID pgtype.UUID) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, listOpenMatchConversationsForIdentity, identityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

