const sumBotUsageSince = `-- name: SumBotUsageSince :one
SELECT COALESCE(sum(prompt_tokens + completion_tokens), 0)::bigint AS tokens,
       COALESCE(sum(replies), 0)::bigint AS replies
FROM bot_usage
WHERE bot_id = $1 AND created_at >= $2
`

type SumBotUsageSinceParams struct {
	BotID     pgtype.UUID        `json:"bot_id"`
	CreatedAt pgtype.Timestamptz `json:"created_at"`
}

type SumBotUsageSinceRow struct {
	Tokens  int64 `json:"tokens"`
	Replies int64 `json:"replies"`
}

// 滑动窗口内的用量（token = prompt + completion）。
func (q *Queries) SumBotUsageSince(ctx context.Context, arg SumBotUsageSinceParams) (SumBotUsageSinceRow, error) {
	row := q.db.QueryRow(ctx, sumBotUsageSince, arg.BotID, arg.CreatedAt)
	var i SumBotUsageSinceRow
	err := row.Scan(&i.Tokens, &i.Replies)
	return i, err
}

